<?php
require __DIR__.'/auth.php';$account=requireLogin();
require dirname(__DIR__).'/includes/bootstrap.php';
require dirname(__DIR__).'/includes/listings.php';
require dirname(__DIR__).'/Config/projects-store.php';
$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
    requireAdmin();adminCsrf();
    $slug=is_string($_POST['slug']??null)?$_POST['slug']:'';
    $publication=is_string($_POST['status']??null)?$_POST['status']:'';
    try{projectSetPublication($slug,$publication);header('Location: ./projects?publication='.rawurlencode($publication),true,303);exit;}
    catch(Throwable $exception){http_response_code(422);$error='Unable to change visibility. Refresh the page and try again.';}
}
$projects=projectData($account['role']==='admin');$properties=listingData($account['role']==='admin');
$query=is_string($_GET['q']??null)?mb_substr(trim($_GET['q']),0,150):'';
$stage=is_string($_GET['development_status']??null)?$_GET['development_status']:'';
if(!in_array($stage,['','Upcoming','Under construction','Completed'],true))$stage='';
$visibility=$account['role']==='admin'&&is_string($_GET['visibility']??null)?$_GET['visibility']:'';
if(!in_array($visibility,['','published','unpublished'],true))$visibility='';
$items=array_values(array_filter($projects,static fn($p)=>($query===''||mb_stripos($p['title'].' '.$p['city'].' '.$p['developer_name'],$query)!==false)&&($stage===''||$p['development_status']===$stage)&&($visibility===''||$p['status']===$visibility)));
$layout=($_GET['layout']??'cards')==='list'?'list':'cards';
$total=count($items);$perPage=6;$pages=max(1,(int)ceil($total/$perPage));$page=min($pages,max(1,(int)(is_scalar($_GET['page']??null)?$_GET['page']:1)));$offset=($page-1)*$perPage;$items=array_slice($items,$offset,$perPage);
$pageLink=static fn($number)=>'./projects?'.http_build_query(['q'=>$query,'development_status'=>$stage,'visibility'=>$visibility,'page'=>$number,'layout'=>$layout]);
$view='projects';$title='Projects';require __DIR__.'/header.php';
?>
<link rel="stylesheet" href="./projects-admin.css?v=<?= filemtime(__DIR__.'/projects-admin.css') ?>">
<section class="page-heading"><div><span class="eyebrow">PROJECT WORKSPACE</span><h1><?= $account['role']==='admin'?'Manage your projects.':'Explore our projects.' ?></h1><p><?= $account['role']==='admin'?'Manage project information, documents and media, then choose when it appears on the website.':'Explore project details, documents, photos and videos in one place.' ?></p></div><?php if($account['role']==='admin'): ?><a class="primary-button" href="./create-project">+ Add project</a><?php endif; ?></section>
<?php if($error): ?><div class="form-error" role="alert"><?= e($error) ?></div><?php endif; ?>
<?php $notice='';if(isset($_GET['created']))$notice='Project created successfully.';elseif(isset($_GET['updated']))$notice='Project updated successfully.';elseif(in_array($_GET['publication']??'', ['published','unpublished'],true))$notice='Project '.$_GET['publication'].' successfully.';if($notice): ?><div class="success-note" role="status"><?= e($notice) ?></div><?php endif; ?>
<section class="stats" aria-label="Project summary"><?php foreach([['Total projects',count($projects),'building'],['Published',count(array_filter($projects,fn($p)=>$p['status']==='published')),'house'],['Under construction',count(array_filter($projects,fn($p)=>$p['development_status']==='Under construction')),'layers'],['Completed',count(array_filter($projects,fn($p)=>$p['development_status']==='Completed')),'crown']] as $stat): ?><article class="stat-card"><div><span><?= e($stat[0]) ?></span><div class="stat-icon"><?= listingIcon($stat[2]) ?></div></div><strong><?= $stat[1] ?></strong></article><?php endforeach; ?></section>
<section class="panel inventory"><div class="panel-title"><div><h2>Project inventory</h2><p><?= $total ?> <?= $total===1?'project':'projects' ?> found</p></div><div class="layout-switch" aria-label="Inventory display"><a href="<?= e('./projects?'.http_build_query(['layout'=>'cards','q'=>$query,'development_status'=>$stage,'visibility'=>$visibility])) ?>" <?= $layout==='cards'?'aria-current="true"':'' ?>><?= listingIcon('grid') ?>Cards</a><a href="<?= e('./projects?'.http_build_query(['layout'=>'list','q'=>$query,'development_status'=>$stage,'visibility'=>$visibility])) ?>" <?= $layout==='list'?'aria-current="true"':'' ?>><?= listingIcon('filter') ?>List</a></div></div>
<form class="table-toolbar project-inventory-toolbar" method="get" action="./projects"><input type="hidden" name="layout" value="<?= e($layout) ?>"><label class="search-field"><?= listingIcon('search') ?><span class="sr-only">Search projects</span><input type="search" name="q" maxlength="150" value="<?= e($query) ?>" placeholder="Search name, location or developer"></label><label><span class="sr-only">Development stage</span><select name="development_status"><option value="">All stages</option><?php foreach(['Upcoming','Under construction','Completed'] as $option): ?><option <?= $stage===$option?'selected':'' ?>><?= e($option) ?></option><?php endforeach; ?></select></label><?php if($account['role']==='admin'): ?><label><span class="sr-only">Website visibility</span><select name="visibility"><option value="">All visibility</option><option value="published" <?= $visibility==='published'?'selected':'' ?>>Published</option><option value="unpublished" <?= $visibility==='unpublished'?'selected':'' ?>>Unpublished</option></select></label><?php endif; ?><button class="primary-button" type="submit">Filter</button><?php if($query!==''||$stage!==''||$visibility!==''): ?><a class="text-link" href="./projects">Reset</a><?php endif; ?></form>
<?php if(!$items): ?><div class="empty-state"><h3>No projects match your search.</h3><p>Try different filters or add your first project.</p></div><?php elseif($layout==='list'): ?><div class="project-admin-list"><?php foreach($items as $project): ?><article class="project-admin-row"><img src="../<?= e(substr($project['image'],2)) ?>" alt="<?= e($project['title']) ?>" width="180" height="120" loading="lazy"><div class="project-admin-row-info"><h3><?= e($project['title']) ?></h3><p><?= e($project['city']) ?> &middot; <?= e($project['type']) ?></p><div><span class="property-publication <?= $project['status']==='published'?'is-published':'' ?>"><?= ucfirst($project['status']) ?></span><span class="subtle-tag"><?= e($project['development_status']) ?></span></div></div><div class="project-admin-row-actions"><?php if($account['role']==='admin'): ?><a class="property-edit-link" href="./create-project?slug=<?= rawurlencode($project['slug']) ?>">Edit</a><form method="post" action="./projects" class="property-publication-form"><input type="hidden" name="csrf" value="<?= e(adminToken()) ?>"><input type="hidden" name="slug" value="<?= e($project['slug']) ?>"><input type="hidden" name="status" value="<?= $project['status']==='published'?'unpublished':'published' ?>"><button type="submit" class="property-entry-button"><?= $project['status']==='published'?'Unpublish':'Publish' ?></button></form><?php endif; ?><?php if($project['status']==='published'): ?><a href="../project.php?slug=<?= rawurlencode($project['slug']) ?>">View &nearr;</a><?php endif; ?></div></article><?php endforeach; ?></div><?php else: ?><div class="admin-inventory-grid"><?php foreach($items as $project): ?><article class="inventory-card"><a href="<?= $project['status']==='published'?'../project.php?slug='.rawurlencode($project['slug']):'./create-project?slug='.rawurlencode($project['slug']) ?>" aria-label="View <?= e($project['title']) ?>"><img src="../<?= e(substr($project['image'],2)) ?>" alt="<?= e($project['title']) ?>" width="600" height="400" loading="lazy"></a><div><div class="inventory-card-badges"><span class="property-publication <?= $project['status']==='published'?'is-published':'' ?>"><?= ucfirst($project['status']) ?></span><span class="subtle-tag"><?= e($project['development_status']) ?></span></div><h3><?= e($project['title']) ?></h3><p><?= e($project['city']) ?> &middot; <?= e($project['type']) ?></p><p><?= e($project['developer_name']) ?></p><strong class="inventory-price"><?= (float)$project['price_from']>0?'From Rs '.number_format((float)$project['price_from']):'Pricing not provided' ?></strong><label class="inventory-progress">Development progress <strong><?= (int)$project['progress'] ?>%</strong><progress max="100" value="<?= (int)$project['progress'] ?>"><?= (int)$project['progress'] ?>%</progress></label><div class="inventory-card-actions"><?php if($account['role']==='admin'): ?><a class="property-edit-link" href="./create-project?slug=<?= rawurlencode($project['slug']) ?>"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="m15 5 4 4M4 20l4-1L20 7a2.8 2.8 0 0 0-4-4L4 15z"/></svg> Edit</a><form method="post" action="./projects" class="property-publication-form"><input type="hidden" name="csrf" value="<?= e(adminToken()) ?>"><input type="hidden" name="slug" value="<?= e($project['slug']) ?>"><input type="hidden" name="status" value="<?= $project['status']==='published'?'unpublished':'published' ?>"><button type="submit" class="property-entry-button"><?= $project['status']==='published'?'Unpublish':'Publish' ?></button></form><?php endif; ?><?php if($project['status']==='published'): ?><a class="inventory-view" href="../project.php?slug=<?= rawurlencode($project['slug']) ?>">View &nearr;</a><?php else: ?><span class="project-draft-note">Hidden on website</span><?php endif; ?></div></div></article><?php endforeach; ?></div><?php endif; ?>
<?php if($total): ?><div class="inventory-pagination"><p>Showing <?= $offset+1 ?>&ndash;<?= $offset+count($items) ?> of <?= $total ?></p><?php if($pages>1): ?><nav aria-label="Project inventory pages"><?php if($page>1): ?><a href="<?= e($pageLink($page-1)) ?>">&lsaquo; Previous</a><?php endif; ?><?php for($i=1;$i<=$pages;$i++): ?><a href="<?= e($pageLink($i)) ?>" <?= $i===$page?'aria-current="page"':'' ?>><?= $i ?></a><?php endfor; ?><?php if($page<$pages): ?><a href="<?= e($pageLink($page+1)) ?>">Next &rsaquo;</a><?php endif; ?></nav><?php endif; ?></div><?php endif; ?>
</section>
